// ═══════════════════════════════════════════════════════════════════════════
// INPUT PROCESSOR
// Validates user input and extracts code blocks for processing
// ═══════════════════════════════════════════════════════════════════════════

const chatInput = $input.first().json.chatInput || '';
const sessionId = $input.first().json.sessionId || $execution.id;

// ─────────────────────────────────────────────────────────────────────────────
// VALIDATION
// ─────────────────────────────────────────────────────────────────────────────
if (!chatInput || chatInput.trim().length < 5) {
  return [{
    json: {
      isValid: false,
      errorType: 'INVALID_INPUT',
      error: 'Please provide a more detailed request (at least 5 characters).',
      sessionId,
      timestamp: new Date().toISOString()
    }
  }];
}

// ─────────────────────────────────────────────────────────────────────────────
// CODE BLOCK EXTRACTION
// ─────────────────────────────────────────────────────────────────────────────
const codeBlockRegex = /```(\w+)?\n?([\s\S]*?)```/g;
const codeBlocks = [];
let match;

while ((match = codeBlockRegex.exec(chatInput)) !== null) {
  codeBlocks.push({
    language: match[1] || 'unknown',
    code: match[2].trim()
  });
}

const providedCode = codeBlocks.length > 0 
  ? codeBlocks.map(b => b.code).join('\n\n')
  : null;

const detectedCodeLang = codeBlocks.length > 0 
  ? codeBlocks[0].language 
  : null;

// Clean message for intent analysis
const cleanMessage = chatInput.replace(/```[\s\S]*?```/g, '[CODE_BLOCK]').trim();

return [{
  json: {
    isValid: true,
    originalInput: chatInput,
    cleanMessage,
    providedCode,
    detectedCodeLang,
    hasCode: !!providedCode,
    codeBlockCount: codeBlocks.length,
    sessionId,
    timestamp: new Date().toISOString()
  }
}];

// ═══════════════════════════════════════════════════════════════════════════
// INTENT CLASSIFIER
// Determines user intent (GENERATE/EXPLAIN/MODIFY) and target language
// ═══════════════════════════════════════════════════════════════════════════

const input = $input.first().json;
const message = input.cleanMessage.toLowerCase();

// ─────────────────────────────────────────────────────────────────────────────
// INTENT DETECTION
// Priority order: EXPLAIN > MODIFY > DOCUMENT > GENERATE
// ─────────────────────────────────────────────────────────────────────────────
const intentPatterns = [
  {
    intent: 'EXPLAIN',
    patterns: ['explain', 'what does', 'how does', 'break down', 'analyze', 
               'understand', 'describe', 'walk through', 'tell me about'],
    priority: 1
  },
  {
    intent: 'MODIFY',
    patterns: ['modify', 'change', 'update', 'fix', 'refactor', 'improve', 
               'optimize', 'enhance', 'add to', 'extend'],
    priority: 2
  },
  {
    intent: 'DOCUMENT',
    patterns: ['document', 'documentation', 'readme', 'how to use', 
               'usage guide', 'api docs'],
    priority: 3
  },
  {
    intent: 'GENERATE',
    patterns: ['generate', 'create', 'write', 'build', 'make', 'code', 
               'implement', 'develop', 'script', 'program', 'design'],
    priority: 4
  }
];

// Default intent based on whether code is provided
let detectedIntent = input.hasCode ? 'EXPLAIN' : 'GENERATE';
let intentConfidence = 'medium';

// Check patterns
for (const { intent, patterns } of intentPatterns.sort((a, b) => a.priority - b.priority)) {
  if (patterns.some(p => message.includes(p))) {
    detectedIntent = intent;
    intentConfidence = 'high';
    break;
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// LANGUAGE DETECTION
// ─────────────────────────────────────────────────────────────────────────────
const languagePatterns = {
  python: {
    keywords: ['python', 'django', 'flask', 'fastapi', 'pandas', 'numpy', 
               'pytorch', 'tensorflow', 'scikit', 'pip'],
    codePatterns: [/def\s+\w+\s*\(/, /import\s+\w+/, /from\s+\w+\s+import/]
  },
  sql: {
    keywords: ['sql', 'mysql', 'postgresql', 'postgres', 'sqlite', 'query', 
               'database', 'select from', 'insert into'],
    codePatterns: [/SELECT\s+/i, /INSERT\s+INTO/i, /CREATE\s+TABLE/i]
  },
  plsql: {
    keywords: ['pl/sql', 'plsql', 'oracle', 'stored procedure', 'trigger', 
               'package', 'cursor'],
    codePatterns: [/CREATE\s+(OR\s+REPLACE\s+)?PROCEDURE/i, /DECLARE\s+/i, /BEGIN\s+/i]
  },
  terraform: {
    keywords: ['terraform', 'tf', 'infrastructure', 'iac', 'aws', 'azure', 
               'gcp', 'provider', 'resource'],
    codePatterns: [/resource\s+"\w+"/, /provider\s+"\w+"/, /variable\s+"\w+"/]
  },
  yaml: {
    keywords: ['yaml', 'yml', 'kubernetes', 'k8s', 'docker-compose', 'ansible', 
               'github actions', 'gitlab ci', 'helm'],
    codePatterns: [/apiVersion:/, /kind:\s*\w+/, /metadata:/]
  },
  csharp: {
    keywords: ['c#', 'csharp', '.net', 'dotnet', 'asp.net', 'entity framework', 
               'blazor', 'wpf', 'unity'],
    codePatterns: [/using\s+System/, /namespace\s+\w+/, /public\s+class\s+\w+/]
  },
  java: {
    keywords: ['java', 'spring', 'springboot', 'maven', 'gradle', 'hibernate', 
               'jpa', 'servlet', 'tomcat'],
    codePatterns: [/public\s+class\s+\w+/, /import\s+java\./, /@SpringBootApplication/]
  },
  javascript: {
    keywords: ['javascript', 'js', 'node', 'nodejs', 'react', 'vue', 'angular', 
               'express', 'next.js', 'npm'],
    codePatterns: [/function\s+\w+\s*\(/, /const\s+\w+\s*=/, /=>\s*\{/]
  },
  typescript: {
    keywords: ['typescript', 'ts', 'angular', 'nestjs', 'deno'],
    codePatterns: [/interface\s+\w+/, /type\s+\w+\s*=/, /:\s*(string|number|boolean)/]
  },
  go: {
    keywords: ['golang', 'go', 'gin', 'echo', 'fiber'],
    codePatterns: [/package\s+\w+/, /func\s+\w+\s*\(/, /import\s+\(/]
  },
  rust: {
    keywords: ['rust', 'cargo', 'tokio', 'actix', 'rocket'],
    codePatterns: [/fn\s+\w+\s*\(/, /let\s+mut\s+/, /impl\s+\w+/]
  },
  bash: {
    keywords: ['bash', 'shell', 'sh', 'script', 'linux', 'unix', 'terminal'],
    codePatterns: [/#!/, /\$\{?\w+\}?/, /if\s+\[\[?/]
  },
  powershell: {
    keywords: ['powershell', 'ps1', 'windows script', 'cmdlet'],
    codePatterns: [/\$\w+\s*=/, /Get-\w+/, /Set-\w+/]
  }
};

// Score each language
let detectedLanguage = 'python';
let languageConfidence = 'low';
let maxScore = 0;

for (const [lang, { keywords, codePatterns }] of Object.entries(languagePatterns)) {
  let score = 0;

  // Check keywords in message
  for (const keyword of keywords) {
    if (message.includes(keyword.toLowerCase())) {
      score += 2;
    }
  }

  // Check code patterns if code is provided
  if (input.providedCode) {
    for (const pattern of codePatterns) {
      if (pattern.test(input.providedCode)) {
        score += 3;
      }
    }
  }

  if (score > maxScore) {
    maxScore = score;
    detectedLanguage = lang;
    languageConfidence = score >= 4 ? 'high' : score >= 2 ? 'medium' : 'low';
  }
}

// Use detected code language if confidence is low
if (input.detectedCodeLang && input.detectedCodeLang !== 'unknown' && languageConfidence === 'low') {
  detectedLanguage = input.detectedCodeLang;
  languageConfidence = 'medium';
}

return [{
  json: {
    ...input,
    intent: detectedIntent,
    intentConfidence,
    language: detectedLanguage,
    languageConfidence
  }
}];

// ═══════════════════════════════════════════════════════════════════════════
// CODE VALIDATOR
// Performs security checks and quality analysis on generated code
// ═══════════════════════════════════════════════════════════════════════════

const input = $input.first().json;

// ─────────────────────────────────────────────────────────────────────────────
// RETRIEVE ORIGINAL CONTEXT FROM INTENT CLASSIFIER
// The Anthropic node only returns its response, so we need to get context
// from earlier nodes in the workflow
// ─────────────────────────────────────────────────────────────────────────────
let originalContext = {};
try {
  originalContext = $('Intent Classifier').first().json || {};
} catch (e) {
  // If node reference fails, try to get from input
  originalContext = input;
}

const language = originalContext.language || input.language || 'python';
const intent = originalContext.intent || input.intent || 'GENERATE';
const sessionId = originalContext.sessionId || input.sessionId || '';
const providedCode = originalContext.providedCode || input.providedCode || '';
const originalInput = originalContext.originalInput || input.originalInput || '';

// ─────────────────────────────────────────────────────────────────────────────
// EXTRACT TEXT FROM ANTHROPIC RESPONSE
// Handle multiple possible response structures from the Anthropic node
// ─────────────────────────────────────────────────────────────────────────────
let generatedText = '';

// Try different response paths (Anthropic node returns data in various formats)
if (input.text) {
  // Simplified output format (most common)
  generatedText = input.text;
} else if (input.content && Array.isArray(input.content)) {
  // Raw API format: content is array of blocks
  generatedText = input.content
    .filter(block => block.type === 'text')
    .map(block => block.text)
    .join('\n');
} else if (input.message?.content) {
  // Nested message format
  if (Array.isArray(input.message.content)) {
    generatedText = input.message.content
      .filter(block => block.type === 'text')
      .map(block => block.text)
      .join('\n');
  } else if (typeof input.message.content === 'string') {
    generatedText = input.message.content;
  }
} else if (input.output) {
  generatedText = input.output;
} else if (input.response) {
  generatedText = input.response;
} else if (typeof input === 'string') {
  generatedText = input;
}

// Fallback: stringify and look for text patterns
if (!generatedText && input) {
  const inputStr = JSON.stringify(input);
  const textMatch = inputStr.match(/"text":\s*"([^"]+)"/s);
  if (textMatch) {
    generatedText = textMatch[1].replace(/\\n/g, '\n').replace(/\\"/g, '"');
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// EXTRACT CODE BLOCKS
// ─────────────────────────────────────────────────────────────────────────────
const codeBlockRegex = /```(\w+)?\n([\s\S]*?)```/g;
const codeBlocks = [];
let match;

while ((match = codeBlockRegex.exec(generatedText)) !== null) {
  codeBlocks.push({
    language: match[1] || language,
    code: match[2].trim()
  });
}

const mainCode = codeBlocks.length > 0 ? codeBlocks[0].code : generatedText;
const codeLanguage = codeBlocks.length > 0 ? codeBlocks[0].language : language;

// ─────────────────────────────────────────────────────────────────────────────
// VALIDATION RESULTS STRUCTURE
// ─────────────────────────────────────────────────────────────────────────────
const validation = {
  hasCode: codeBlocks.length > 0 || mainCode.length > 20,
  securityIssues: [],
  warnings: [],
  suggestions: [],
  codeMetrics: {
    lines: mainCode.split('\n').length,
    characters: mainCode.length,
    functions: 0,
    classes: 0,
    complexity: 'low'
  }
};

// ─────────────────────────────────────────────────────────────────────────────
// SECURITY CHECKS (CRITICAL)
// ─────────────────────────────────────────────────────────────────────────────
const securityPatterns = [
  {
    pattern: /password\s*=\s*["'][^"']+["']/gi,
    issue: '🔐 CRITICAL: Hardcoded password detected - use environment variables',
    severity: 'critical'
  },
  {
    pattern: /api[_-]?key\s*=\s*["'][A-Za-z0-9_-]{10,}["']/gi,
    issue: '🔐 CRITICAL: Hardcoded API key detected - use environment variables',
    severity: 'critical'
  },
  {
    pattern: /secret\s*=\s*["'][^"']+["']/gi,
    issue: '🔐 CRITICAL: Hardcoded secret detected - use environment variables',
    severity: 'critical'
  },
  {
    pattern: /token\s*=\s*["'][A-Za-z0-9_-]{20,}["']/gi,
    issue: '🔐 CRITICAL: Hardcoded token detected - use environment variables',
    severity: 'critical'
  },
  {
    pattern: /eval\s*\(/g,
    issue: '⚠️ HIGH: eval() usage detected - potential code injection vulnerability',
    severity: 'high'
  },
  {
    pattern: /exec\s*\(/g,
    issue: '⚠️ HIGH: exec() usage detected - validate input carefully',
    severity: 'high'
  },
  {
    pattern: /subprocess\.(call|run|Popen)\s*\([^)]*shell\s*=\s*True/g,
    issue: '⚠️ HIGH: Shell=True in subprocess - potential command injection',
    severity: 'high'
  },
  {
    pattern: /innerHTML\s*=/g,
    issue: '⚠️ HIGH: innerHTML assignment - potential XSS vulnerability',
    severity: 'high'
  },
  {
    pattern: /document\.write\s*\(/g,
    issue: '⚠️ HIGH: document.write() usage - potential XSS vulnerability',
    severity: 'high'
  }
];

for (const { pattern, issue } of securityPatterns) {
  if (pattern.test(mainCode)) {
    validation.securityIssues.push(issue);
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// LANGUAGE-SPECIFIC CHECKS
// ─────────────────────────────────────────────────────────────────────────────

// Python
if (codeLanguage === 'python') {
  validation.codeMetrics.functions = (mainCode.match(/def\s+\w+\s*\(/g) || []).length;
  validation.codeMetrics.classes = (mainCode.match(/class\s+\w+/g) || []).length;

  if (/except\s*:/.test(mainCode)) {
    validation.warnings.push('⚠️ Bare except clause - specify exception types');
  }
  if (!/if\s+__name__\s*==\s*["']__main__["']/.test(mainCode) && /def\s+main\s*\(/.test(mainCode)) {
    validation.suggestions.push('💡 Consider adding `if __name__ == "__main__":` guard');
  }
  if (/print\s*\(/.test(mainCode) && validation.codeMetrics.lines > 30) {
    validation.suggestions.push('💡 Consider using logging module instead of print()');
  }
}

// SQL / PL/SQL
if (codeLanguage === 'sql' || codeLanguage === 'plsql') {
  if (/SELECT\s+\*\s+FROM/i.test(mainCode)) {
    validation.suggestions.push('💡 Specify columns instead of SELECT * for better performance');
  }
  if (/['"]?\s*\+\s*\w+\s*\+\s*['"]?/.test(mainCode)) {
    validation.securityIssues.push('🔐 CRITICAL: String concatenation in SQL - use parameterized queries');
  }
}

// Terraform
if (codeLanguage === 'terraform' || codeLanguage === 'tf') {
  validation.codeMetrics.functions = (mainCode.match(/resource\s+"\w+"/g) || []).length;

  if (!/required_version/.test(mainCode) && mainCode.length > 50) {
    validation.suggestions.push('💡 Add terraform required_version constraint');
  }
  if (/access_key\s*=|secret_key\s*=/.test(mainCode)) {
    validation.securityIssues.push('🔐 CRITICAL: AWS credentials in Terraform - use environment variables or IAM roles');
  }
}

// JavaScript / TypeScript
if (codeLanguage === 'javascript' || codeLanguage === 'typescript') {
  validation.codeMetrics.functions = (mainCode.match(/function\s+\w+|=>\s*[{(]|async\s+function/g) || []).length;
  validation.codeMetrics.classes = (mainCode.match(/class\s+\w+/g) || []).length;

  if (/var\s+/.test(mainCode)) {
    validation.suggestions.push('💡 Use let/const instead of var for better scoping');
  }
  if (/==(?!=)/.test(mainCode)) {
    validation.warnings.push('⚠️ Loose equality (==) used - consider strict equality (===)');
  }
}

// Java
if (codeLanguage === 'java') {
  validation.codeMetrics.classes = (mainCode.match(/class\s+\w+/g) || []).length;
  validation.codeMetrics.functions = (mainCode.match(/public\s+(static\s+)?\w+\s+\w+\s*\(/g) || []).length;

  if (/System\.out\.println/.test(mainCode) && validation.codeMetrics.lines > 30) {
    validation.suggestions.push('💡 Use a logging framework (SLF4J/Log4j) instead of System.out');
  }
}

// C#
if (codeLanguage === 'csharp') {
  validation.codeMetrics.classes = (mainCode.match(/class\s+\w+/g) || []).length;
  validation.codeMetrics.functions = (mainCode.match(/public\s+(static\s+)?(async\s+)?\w+\s+\w+\s*\(/g) || []).length;

  if (/Console\.WriteLine/.test(mainCode) && validation.codeMetrics.lines > 30) {
    validation.suggestions.push('💡 Use ILogger for logging in production applications');
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// COMPLEXITY ESTIMATION
// ─────────────────────────────────────────────────────────────────────────────
const nestedLoops = (mainCode.match(/(for|while|foreach)[\s\S]*?(for|while|foreach)/g) || []).length;
const conditionals = (mainCode.match(/if|else|switch|case|\?.*:/g) || []).length;

if (nestedLoops > 2 || conditionals > 15) {
  validation.codeMetrics.complexity = 'high';
  validation.suggestions.push('💡 Consider refactoring to reduce complexity');
} else if (nestedLoops > 0 || conditionals > 8) {
  validation.codeMetrics.complexity = 'medium';
}

// ─────────────────────────────────────────────────────────────────────────────
// FINAL VALIDATION
// ─────────────────────────────────────────────────────────────────────────────
const isValid = validation.hasCode && 
  validation.securityIssues.filter(i => i.includes('CRITICAL')).length === 0;

return [{
  json: {
    // Original context from Intent Classifier
    language,
    intent,
    sessionId,
    providedCode,
    originalInput,
    // Code extraction results
    code: mainCode,
    codeLanguage,
    allCodeBlocks: codeBlocks,
    validation,
    isValid,
    generatedText
  }
}];

// ═══════════════════════════════════════════════════════════════════════════
// CODE FILE CREATOR
// Creates downloadable files based on intent:
// - GENERATE/MODIFY: Code file with appropriate extension (.py, .js, etc.)
// - EXPLAIN: Text file with the explanation (.txt)
// ═══════════════════════════════════════════════════════════════════════════

const input = $input.first().json;
const intent = input.intent || 'GENERATE';
const language = input.codeLanguage || input.language || 'text';
const timestamp = Date.now();

// ─────────────────────────────────────────────────────────────────────────────
// DETERMINE FILE CONTENT BASED ON INTENT
// ─────────────────────────────────────────────────────────────────────────────
let fileContent = '';
let extension = '.txt';
let mimeType = 'text/plain';
let baseFilename = '';

if (intent === 'EXPLAIN') {
  // For EXPLAIN: Create a text file with the full explanation
  fileContent = input.generatedText || '';
  extension = '.txt';
  mimeType = 'text/plain';
  baseFilename = 'code_explanation';

  // Add header to the explanation file
  const header = `════════════════════════════════════════════════════════════════════════════════
                         CODE EXPLANATION DOCUMENT
════════════════════════════════════════════════════════════════════════════════
Generated: ${new Date().toISOString()}
Language: ${language.charAt(0).toUpperCase() + language.slice(1)}
════════════════════════════════════════════════════════════════════════════════

`;
  fileContent = header + fileContent;

} else {
  // For GENERATE/MODIFY: Create a code file with the extracted code
  fileContent = input.code || '';

  // If code is still empty, try to extract from generatedText
  if (!fileContent && input.generatedText) {
    const codeBlockRegex = /```(?:\w+)?\n([\s\S]*?)```/g;
    const match = codeBlockRegex.exec(input.generatedText);
    if (match) {
      fileContent = match[1].trim();
    } else {
      fileContent = input.generatedText;
    }
  }

  baseFilename = intent === 'MODIFY' ? 'modified_code' : 'generated_code';

  // ─────────────────────────────────────────────────────────────────────────────
  // LANGUAGE TO FILE EXTENSION MAPPING
  // ─────────────────────────────────────────────────────────────────────────────
  const extensionMap = {
    python: '.py',
    javascript: '.js',
    typescript: '.ts',
    java: '.java',
    csharp: '.cs',
    sql: '.sql',
    plsql: '.sql',
    terraform: '.tf',
    yaml: '.yaml',
    yml: '.yml',
    go: '.go',
    rust: '.rs',
    bash: '.sh',
    shell: '.sh',
    sh: '.sh',
    powershell: '.ps1',
    php: '.php',
    ruby: '.rb',
    perl: '.pl',
    scala: '.scala',
    kotlin: '.kt',
    swift: '.swift',
    r: '.r',
    matlab: '.m',
    lua: '.lua',
    groovy: '.groovy',
    haskell: '.hs',
    elixir: '.ex',
    clojure: '.clj',
    dart: '.dart',
    cpp: '.cpp',
    c: '.c',
    'c++': '.cpp',
    objectivec: '.m',
    html: '.html',
    css: '.css',
    scss: '.scss',
    sass: '.sass',
    less: '.less',
    json: '.json',
    xml: '.xml',
    markdown: '.md',
    md: '.md',
    dockerfile: 'Dockerfile',
    makefile: 'Makefile',
    text: '.txt'
  };

  // ─────────────────────────────────────────────────────────────────────────────
  // MIME TYPE MAPPING
  // ─────────────────────────────────────────────────────────────────────────────
  const mimeTypeMap = {
    '.py': 'text/x-python',
    '.js': 'application/javascript',
    '.ts': 'application/typescript',
    '.java': 'text/x-java-source',
    '.cs': 'text/x-csharp',
    '.sql': 'application/sql',
    '.tf': 'text/plain',
    '.yaml': 'application/x-yaml',
    '.yml': 'application/x-yaml',
    '.go': 'text/x-go',
    '.rs': 'text/x-rust',
    '.sh': 'application/x-sh',
    '.ps1': 'application/x-powershell',
    '.php': 'application/x-php',
    '.rb': 'application/x-ruby',
    '.pl': 'text/x-perl',
    '.scala': 'text/x-scala',
    '.kt': 'text/x-kotlin',
    '.swift': 'text/x-swift',
    '.r': 'text/x-r',
    '.m': 'text/x-matlab',
    '.lua': 'text/x-lua',
    '.groovy': 'text/x-groovy',
    '.hs': 'text/x-haskell',
    '.ex': 'text/x-elixir',
    '.clj': 'text/x-clojure',
    '.dart': 'application/dart',
    '.cpp': 'text/x-c++src',
    '.c': 'text/x-csrc',
    '.html': 'text/html',
    '.css': 'text/css',
    '.scss': 'text/x-scss',
    '.sass': 'text/x-sass',
    '.less': 'text/x-less',
    '.json': 'application/json',
    '.xml': 'application/xml',
    '.md': 'text/markdown',
    '.txt': 'text/plain',
    'Dockerfile': 'text/plain',
    'Makefile': 'text/plain'
  };

  extension = extensionMap[language.toLowerCase()] || '.txt';
  mimeType = mimeTypeMap[extension] || 'text/plain';
}

// ─────────────────────────────────────────────────────────────────────────────
// GENERATE FILENAME
// ─────────────────────────────────────────────────────────────────────────────
const filename = extension.startsWith('.') 
  ? `${baseFilename}_${timestamp}${extension}`
  : extension; // For special files like Dockerfile, Makefile

// ─────────────────────────────────────────────────────────────────────────────
// CREATE BINARY DATA
// ─────────────────────────────────────────────────────────────────────────────
const binaryData = Buffer.from(fileContent, 'utf-8').toString('base64');

return [{
  json: {
    ...input,
    fileContent,
    filename,
    extension,
    mimeType,
    fileSize: fileContent.length,
    fileSizeKB: Math.round(fileContent.length / 1024 * 100) / 100
  },
  binary: {
    data: {
      data: binaryData,
      mimeType: mimeType,
      fileName: filename,
      fileExtension: extension.replace('.', '')
    }
  }
}];

// ═══════════════════════════════════════════════════════════════════════════
// RESPONSE FORMATTER
// Creates polished, informative chat response with file attachment
// Handles different output types based on intent:
// - GENERATE/MODIFY: Code file with code preview
// - EXPLAIN: Explanation text file with explanation preview
// ═══════════════════════════════════════════════════════════════════════════

const input = $input.first().json;
const binary = $input.first().binary;
const intent = input.intent || 'GENERATE';
const language = input.codeLanguage || input.language || 'text';
const code = input.code || '';
const generatedText = input.generatedText || '';
const fileContent = input.fileContent || '';
const validation = input.validation || {};
const filename = input.filename || 'output.txt';
const extension = input.extension || '.txt';
const fileSize = input.fileSizeKB || 0;

let response = '';
const langDisplay = language.charAt(0).toUpperCase() + language.slice(1);

// ─────────────────────────────────────────────────────────────────────────────
// HEADER
// ─────────────────────────────────────────────────────────────────────────────

if (intent === 'GENERATE') {
  response += `✅ **Code Generated Successfully!**\n\n`;
} else if (intent === 'EXPLAIN') {
  response += `📖 **Code Explanation Ready!**\n\n`;
} else if (intent === 'MODIFY') {
  response += `🔧 **Code Modified Successfully!**\n\n`;
}

// ─────────────────────────────────────────────────────────────────────────────
// CONTENT BASED ON INTENT
// ─────────────────────────────────────────────────────────────────────────────

if (intent === 'EXPLAIN') {
  // For EXPLAIN: Show explanation details and preview
  response += `**Analyzed Language:** ${langDisplay}\n`;
  response += `**Explanation Length:** ${fileContent.split('\n').length} lines\n\n`;

  // Show the full explanation in the chat (or truncated if very long)
  const explanationLines = generatedText.split('\n');
  const maxPreviewLines = 50;

  if (explanationLines.length > maxPreviewLines) {
    response += '### 📖 Explanation Preview\n\n';
    response += explanationLines.slice(0, maxPreviewLines).join('\n');
    response += `\n\n*... (${explanationLines.length - maxPreviewLines} more lines - download the attached file for the complete explanation)*\n\n`;
  } else {
    response += '### 📖 Code Explanation\n\n';
    response += generatedText;
    response += '\n\n';
  }

  // File attachment notice
  response += '### 📎 Explanation Document Attached\n';
  response += `**Filename:** \`${filename}\`\n`;
  response += `**Format:** Text Document (.txt)\n`;
  response += `**Size:** ${fileSize} KB\n\n`;
  response += 'Download the attached file for the complete explanation document!\n\n';

  // Next steps for EXPLAIN
  response += '---\n';
  response += '**What\'s next?**\n';
  response += '• Ask me to explain a specific part in more detail\n';
  response += '• Request modifications or improvements to the code\n';
  response += '• Generate similar code with different requirements\n';
  response += '• Ask about best practices or alternatives';

} else {
  // For GENERATE/MODIFY: Show code metrics and preview
  response += `**Language:** ${langDisplay}\n`;
  response += `**Lines:** ${validation.codeMetrics?.lines || code.split('\n').length}\n`;
  if (validation.codeMetrics?.functions) {
    response += `**Functions:** ${validation.codeMetrics.functions}\n`;
  }
  if (validation.codeMetrics?.classes) {
    response += `**Classes:** ${validation.codeMetrics.classes}\n`;
  }
  if (validation.codeMetrics?.complexity) {
    response += `**Complexity:** ${validation.codeMetrics.complexity}\n`;
  }
  response += '\n';

  // Validation alerts
  if (validation.securityIssues?.length > 0) {
    response += '### 🔐 Security Issues\n';
    validation.securityIssues.forEach(issue => {
      response += `${issue}\n`;
    });
    response += '\n';
  }

  if (validation.warnings?.length > 0) {
    response += '### ⚠️ Warnings\n';
    validation.warnings.forEach(warning => {
      response += `${warning}\n`;
    });
    response += '\n';
  }

  if (validation.suggestions?.length > 0) {
    response += '### 💡 Suggestions\n';
    validation.suggestions.forEach(suggestion => {
      response += `${suggestion}\n`;
    });
    response += '\n';
  }

  // Code preview
  const codeLines = code.split('\n');
  const previewLines = 30;
  const preview = codeLines.slice(0, previewLines).join('\n');
  const truncated = codeLines.length > previewLines;

  response += '### 📄 Code Preview\n';
  response += '```' + language + '\n';
  response += preview;
  if (truncated) {
    response += '\n// ... (' + (codeLines.length - previewLines) + ' more lines - see attached file for full code)';
  }
  response += '\n```\n\n';

  // File attachment notice
  response += '### 📎 Code File Attached\n';
  response += `**Filename:** \`${filename}\`\n`;
  response += `**Extension:** \`${extension}\`\n`;
  response += `**Size:** ${fileSize} KB\n\n`;
  response += 'Download the attached file to get the complete, ready-to-use code!\n\n';

  // Next steps for GENERATE/MODIFY
  response += '---\n';
  response += '**What\'s next?**\n';
  response += '• Ask me to explain any part of the code\n';
  response += '• Request modifications or improvements\n';
  response += '• Generate unit tests for this code\n';
  response += '• Create code for a different task\n';
  response += '• Ask about best practices or alternatives';
}

// Pass through binary data
return [{
  json: {
    response,
    sessionId: input.sessionId,
    language,
    intent,
    filename,
    extension
  },
  binary: binary
}];

// ═══════════════════════════════════════════════════════════════════════════
// ERROR HANDLER
// Creates user-friendly error messages with recovery suggestions
// ═══════════════════════════════════════════════════════════════════════════

const input = $input.first().json;
const error = input.error || 'An unexpected error occurred';
const errorType = input.errorType || 'UNKNOWN';
const sessionId = input.sessionId || '';

// ─────────────────────────────────────────────────────────────────────────────
// ERROR MESSAGES
// ─────────────────────────────────────────────────────────────────────────────

const errorMessages = {
  INVALID_INPUT: {
    title: 'Invalid Request',
    message: 'I couldn\'t understand your request.',
    suggestions: [
      'Provide more details about what you want to build',
      'Mention the programming language (e.g., "Python", "Java")',
      'For code explanations, paste your code in a code block'
    ]
  },
  LLM_ERROR: {
    title: 'Generation Error',
    message: 'I encountered an issue while generating the code.',
    suggestions: [
      'Try simplifying your request',
      'Break down complex requirements into smaller parts',
      'Try again in a few moments'
    ]
  },
  FILE_ERROR: {
    title: 'File Generation Issue',
    message: 'The code was generated but file creation failed.',
    suggestions: [
      'The code is still available in the response',
      'You can copy the code directly from the preview',
      'Try requesting the code again'
    ]
  },
  TIMEOUT: {
    title: 'Request Timeout',
    message: 'The request took too long to process.',
    suggestions: [
      'Try a simpler request',
      'Break your request into smaller parts',
      'Try again in a few moments'
    ]
  },
  UNKNOWN: {
    title: 'Unexpected Error',
    message: 'Something went wrong.',
    suggestions: [
      'Please try again',
      'Rephrase your request',
      'Contact support if the issue persists'
    ]
  }
};

const errorInfo = errorMessages[errorType] || errorMessages.UNKNOWN;

// ─────────────────────────────────────────────────────────────────────────────
// BUILD RESPONSE
// ─────────────────────────────────────────────────────────────────────────────

let response = `❌ **${errorInfo.title}**\n\n`;
response += `${errorInfo.message}\n\n`;

if (error && error !== errorInfo.message) {
  response += `*Details: ${error}*\n\n`;
}

response += '**Tips to resolve:**\n';
errorInfo.suggestions.forEach(suggestion => {
  response += `• ${suggestion}\n`;
});

response += '\n**Example requests:**\n';
response += '• "Generate a Python FastAPI REST API for user management"\n';
response += '• "Create Terraform code for AWS Lambda with API Gateway"\n';
response += '• "Explain this code: ```python\\ndef example(): ...```"\n';

response += '\n*If the problem persists, try simplifying your request or contact support.*';

return [{
  json: {
    response,
    isError: true,
    errorType,
    sessionId
  }
}];
